import {clauses,sources,testCases} from './content.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'£'+Number(n||0).toLocaleString('en-GB'),date=s=>s?new Date(s).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'—';
let state,role=sessionStorage.getItem('guarantor-demo-role')||'admin',selected=new URLSearchParams(location.search).get('g')||'g1',officeTab='overview',reviewApplicant='83',recordView='enquiry',busy=false;
const page=location.pathname.slice(1)||'office',g=()=>state.guarantors.find(g=>g.id===selected)||state.guarantors[0],tenant=x=>state.tenants.find(t=>t.id===(x||g()).tenantId),canEdit=()=>role!=='viewer';
const icon='<svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M5 19V13L20 3l15 10v6M9 15v19h9V23h5v11h9V15M4 37h33" stroke="currentColor" stroke-width="4"/></svg>';
const brand=`<div class="brand">${icon}<span>Fleming<br>Lettings</span></div>`;
const tag=(text,colour='')=>`<span class="tag ${colour}">${esc(text)}</span>`;
const statusNames={nominated:'Not requested',invited:'Awaiting guarantor',submitted:'Office review needed',changes_requested:'Changes requested',rejected:'Rejected',declined:'Declined',withdrawn:'Withdrawn',approved:'Approved · agreement pending',complete:'Complete'};
const statusColour=s=>s==='complete'?'green':['rejected','declined','withdrawn'].includes(s)?'red':'amber';
const link=(p,x=g())=>'/'+p+'?g='+encodeURIComponent(x.id)+(p==='apply'||p==='agreement'?'&token='+encodeURIComponent(x.invitation?.token||''):'');
function btn(text,action,cls='',disabled=false,extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${text}</button>`;}
function field(label,name,value='',type='text',required=true,wide=false){return `<label class="field ${wide?'wide':''}"><span>${label}${required?' *':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''}></label>`;}
function check(name,text){return `<label class="check"><input type="checkbox" name="${name}" required><span>${text}</span></label>`;}
function selectField(label,name,options,value){return `<label class="field"><span>${label} *</span><select name="${name}" required>${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function rows(d){return Object.entries(d).map(([label,value])=>`<div class="datarow"><span>${esc(label)}</span><span>${esc(value||'—')}</span></div>`).join('');}
const actionButtons=()=>`<a class="btn small" href="${link('email')}">Preview email</a><a class="btn small" href="${link('apply')}">Open guarantor form ↗</a>`;
function notice(text,colour=''){return `<div class="notice ${colour}"><span aria-hidden="true">${colour==='green'?'✓':'△'}</span><div>${text}</div></div>`;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),6000);}
async function refresh(force=false){const next=await fetch('/demo/state').then(r=>r.json());if(force||!state||state.version!==next.version){state=next;render();}}
async function act(body){if(busy)return;busy=true;try{const r=await fetch('/demo/action',{method:'POST',headers:{'Content-Type':'application/json','x-demo-role':role},body:JSON.stringify(body)}),result=await r.json();if(!r.ok)throw Error(result.error);state=result;render();return true;}catch(e){toast(e.message);return false;}finally{busy=false;}}
function shell(content,publicPage=false){const nav=[['office','Office onboarding'],['tenant','Tenant form'],['email','Email'],['apply','Guarantor form'],['record','Record'],['agreement','Guarantee'],['plan','Test plan']];return `<div class="preview"><strong>TEST PREVIEW · fictional records · nothing sent or signed live</strong><nav aria-label="Preview screens">${nav.map(([p,t])=>`<a href="${link(p)}" ${p===page?'aria-current="page"':''}>${t}</a>`).join('')}</nav></div>${publicPage?'':`<header class="top">${brand}<div class="right"><button class="icon bell" data-action="notifications" aria-label="Notifications"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>${state.notifications.some(n=>!n.read)?'<b>'+state.notifications.filter(n=>!n.read).length+'</b>':''}</button><label class="sr-only" for="demo-role">Preview access level</label><select id="demo-role" class="pillselect">${['admin','manager','staff','viewer'].map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select><span class="capsule">${role==='admin'?'Robert Fleming':role==='viewer'?'Read-only user':role==='manager'?'Office Manager':'Marie Ellis'}</span></div></header>`}${content}`;}
function appLayout(content){return `<div class="wrap"><div class="layout"><aside class="appnav" aria-label="CRM navigation"><div>⌂ &nbsp; Dashboard</div><div>⌑ &nbsp; Properties</div><div>♙ &nbsp; Landlords</div><div>♧ &nbsp; Tenants</div><div class="active">▤ &nbsp; Tenant Enquiries</div><div>▦ &nbsp; Team Calendar</div><div>£ &nbsp; Financials</div><div>⚙ &nbsp; Settings</div><p class="small muted" style="padding:18px">These surroundings show where the new stage fits in your CRM.</p></aside><main>${content}</main></div></div>`;}
function stageIcon(i){const paths=['<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>','<path d="m9 12 2 2 4-4"/><circle cx="12" cy="12" r="9"/>','<path d="m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7z"/>','<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18"/>','<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v2"/>','<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5M14 3v6h6M10 16l8-8 3 3-8 8-4 1z"/>','<path d="M17 5a5 5 0 0 0-9 3v11m-3-7h10M5 20h14"/>','<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>','<circle cx="12" cy="7" r="4"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>'];return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[i]+'</svg>';}
function guarantorOffice(){const x=g(),bad=blockers(),c=x.credit,docsDone=x.documents.filter(d=>d.current&&d.review==='approved').length;return `<main class="onboarding-preview"><header class="onboarding-header"><div class="applicant-avatar">J</div><div class="applicant-title"><h1>Jamie Taylor <span class="joint-label">Joint applicant: Casey Taylor</span></h1><p>24 Example Gardens, Wolverhampton, WV10 9TG</p></div><div class="onboarding-progress"><span>Progress</span><strong>${state.ready?'3':'2'}/8</strong></div><a class="btn icon" href="${link('record')}" aria-label="Close tenant onboarding"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></a></header><div class="wizard"><nav class="steps" aria-label="Onboarding stages">${['Request Holding Deposit','Deposit Received & Application','Application Review','Run Credit Check','Tenancy Agreement','Final Balance','Schedule Handover','Convert to Tenant'].map((t,i)=>`<div class="step ${i<2?'done':''} ${i===2?'current':''}" ${i===2?'aria-current="step"':''}>${stageIcon(i>3?i+1:i)}<span>${t}</span></div>`).join('')}<p class="small muted stage-note">Earlier stages completed in this sample.</p></nav><section class="workspace"><div class="cardhead"><div><h2>Guarantor & referencing</h2><p class="muted">Invite, verify and agree the guarantee before issuing the tenancy.</p></div>${tag(state.ready?'Complete':'Action needed',state.ready?'green':'amber')}</div><div class="row" style="flex-wrap:wrap"><label class="field" style="min-width:250px;flex:1"><span>Guarantor / applicant</span><select id="guarantor-picker">${state.guarantors.map(o=>`<option value="${o.id}" ${o.id===x.id?'selected':''}>${esc(o.details.name)} → ${esc(tenant(o).name)}</option>`).join('')}</select></label>${btn('Add guarantor','add','',!canEdit())}</div><div class="progresscards"><div><span class="small muted">Application</span><strong>${esc(statusNames[x.status])}</strong></div><div><span class="small muted">Identity & documents</span><strong>${docsDone}/3 approved</strong></div><div><span class="small muted">Credit report</span><strong>${esc(c.status.replaceAll('_',' '))}</strong></div><div><span class="small muted">Guarantee</span><strong>${esc(x.agreement.status.replaceAll('_',' '))}</strong></div></div><div class="tabs" role="group" aria-label="Guarantor stage sections">${[['overview','Request & details'],['review','Review & credit'],['signing','Agreement'],['activity','Activity audit']].map(([id,name])=>btn(name,'tab','',false,`data-tab="${id}" aria-pressed="${officeTab===id}"`)).join('')}</div>${officeTab==='overview'?overview(x):officeTab==='review'?review(x):officeTab==='signing'?signing(x):audit()}${notice(state.ready?'All required guarantors have completed the test checks and attestations. The next tenancy stage is ready in this preview.':'Complete guarantor checks and the agreement before progressing to the tenancy agreement.',state.ready?'green':'neutral')}<div class="actions">${btn('Reset demonstration','reset','small',role!=='admin')}<a class="btn small" href="/plan">View test plan & legal notes</a></div></section></div></main>`;}

function office(){
 const applicant=state.tenants.find(t=>t.id===reviewApplicant)||state.tenants[0],linked=state.guarantors.find(x=>x.tenantId===applicant.id&&!['rejected','declined'].includes(x.status));if(linked)selected=linked.id;
 let html=guarantorOffice();const start=html.indexOf('<section class="workspace">'),end=html.lastIndexOf('</section>');const inner=html.slice(start+27,end);
 const question=`<div class="review-heading"><div><h2>Application Review</h2><p class="muted">Review the application and confirm whether a guarantor is needed.</p></div>${tag(applicant.guarantorRequired===null?'Decision needed':applicant.guarantorRequired?'Guarantor required':'Not required',applicant.guarantorRequired===false?'green':'amber')}</div><section class="requirement-panel"><label class="field"><span>Applicant</span><select id="review-applicant">${state.tenants.map(t=>`<option value="${t.id}" ${t.id===applicant.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><div class="requirement-question"><h3>Is a guarantor required?</h3><div class="row">${btn('Yes','require-yes',applicant.guarantorRequired===true?'primary':'',!canEdit(),`aria-pressed="${applicant.guarantorRequired===true}"`)}${btn('No','require-no',applicant.guarantorRequired===false?'primary':'',!canEdit(),`aria-pressed="${applicant.guarantorRequired===false}"`)}</div></div></section>`;
 let body='';if(applicant.guarantorRequired===true){body=linked?`<div class="guarantor-section">${inner}</div>`:`<section class="pane spaced"><h3>Guarantor details</h3><p class="muted">No guarantor was entered on this applicant’s form. Add their details to prepare a request.</p><div class="actions">${btn('Add guarantor','add','primary',!canEdit())}</div></section>`;}
 else if(applicant.guarantorRequired===false){body=notice('No guarantor is required for '+esc(applicant.name)+'. Guarantor checks will not block this applicant’s onboarding.','green')+'<p class="small muted">Any previous nomination remains on the record. Existing invitation links are withdrawn when the requirement is removed.</p>';}
 else{body=`<section class="pane nomination-summary"><div class="cardhead"><h3>Guarantor entered on the tenant’s application</h3>${tag(linked?'Details available':'None provided','blue')}</div>${linked?rows({'Name':linked.details.name,'Email':linked.details.email,'Telephone':linked.details.phone,'Relationship':linked.details.relationship}):'<p class="muted">The office can add a guarantor after selecting Yes.</p>'}<p class="small muted spaced">Select Yes to pre-fill the request using these details. This does not send an invitation.</p></section>`;}
 return html.slice(0,start)+'<section class="workspace application-review">'+question+body+'</section>'+html.slice(end+10);
}

function blockers(){const x=g(),b=[];if(!['submitted','approved','complete'].includes(x.status))b.push('Application not submitted');for(const kind of ['Primary ID','Secondary ID','Bank statements'])if(!x.documents.some(d=>d.current&&d.kind===kind&&d.review==='approved'))b.push(kind+' awaiting approval');if(x.credit.status!=='reviewed')b.push('Credit report awaiting office review');return b;}
function overview(x){return `<div class="grid2"><section class="pane"><div class="cardhead"><h3>Guarantor details</h3>${tag(x.source==='Guarantor submission'?'Guarantor supplied':'Pre-populated','blue')}</div>${rows({'Full name':x.details.name,'Email':x.details.email,'Telephone':x.details.phone,'For applicant':tenant(x).name,'Relationship':x.details.relationship,'Address':[x.details.address,x.details.city,x.details.postcode].filter(Boolean).join(', '),'Source':x.source})}<p class="small muted spaced">Submitted details update the linked record; previous values are retained.</p></section><section class="pane"><h3>Application request</h3>${tag(statusNames[x.status],statusColour(x.status))}<p class="spaced">Send the guarantor their own link to confirm the applicant, complete their details and upload evidence.</p>${x.invitation?`<p class="small muted spaced">Link ${x.invitation.revoked?'withdrawn':'expires '+date(x.invitation.expires)} · demo delivery only</p>`:''}<div class="actions">${btn(x.invitation?'Prepare new test invitation':'Prepare test invitation','invite','primary',!canEdit()||['approved','complete','rejected','declined'].includes(x.status))}${actionButtons()}${btn('Withdraw link','revoke','small danger',!canEdit()||!x.invitation||x.invitation.revoked)}</div>${notice('A test invitation is stored in this preview. No email or SMS is sent.','neutral')}${x.reason?notice('<strong>Office message</strong><br>'+esc(x.reason),'red'):''}</section></div>${state.pendingNomination?notice('A later tenant nomination is waiting for office review. It has not overwritten the guarantor’s submitted information.'):''}`;}
function review(x){return `<div class="grid2"><section class="pane"><h3>Documents for review</h3>${x.documents.filter(d=>d.current).length?x.documents.filter(d=>d.current).map(d=>`<div class="doc"><div class="row"><div><strong>${esc(d.kind)}</strong><p class="small muted">${esc(d.name)}</p></div>${tag(d.review,d.review==='approved'?'green':d.review==='rejected'?'red':'amber')}</div>${d.reason?`<p class="small error">${esc(d.reason)}</p>`:''}<div class="actions"><a class="btn small" target="_blank" href="/demo/files/${d.id}">View file</a>${btn('Approve','doc-approve','small',!canEdit()||x.status!=='submitted',`data-doc="${d.id}"`)}${btn('Reject','doc-reject','small danger',!canEdit()||x.status!=='submitted',`data-doc="${d.id}"`)}</div></div>`).join(''):'<p class="muted">Documents will appear when the guarantor uploads them.</p>'}<p class="small muted spaced">Replaced files remain in the record history. Each new version needs review.</p></section><section class="pane"><h3>Guarantor credit report</h3>${tag(x.credit.status.replaceAll('_',' '),'blue')}<p class="spaced">Request a guarantor report after the application and credit-check authority have been received.</p><div class="actions">${btn('Run demo credit check','credit_start','',!canEdit()||x.status!=='submitted'||x.credit.status!=='not_started')}${btn('Receive sample report','credit_result','',!canEdit()||x.credit.status!=='requested')}</div>${x.credit.report?`<div class="notice neutral">${esc(x.credit.report)}</div>${x.credit.reviewNote?`<p><strong>Reviewed by ${esc(x.credit.reviewedBy)}</strong><br>${esc(x.credit.reviewNote)}</p>`:btn('Record report review','credit-review','primary',!canEdit())}`:''}<p class="small muted spaced">Canopy connection: not configured. This demonstration uses a provider simulator.</p><details><summary>Future Canopy integration</summary><p class="small spaced">Separate guarantor request, applicant relationship and application revision. Provider events update the reference status; the office retains the approval decision. Read the implementation plan for the verified API mapping.</p></details></section></div><div class="pane spaced"><h3>Office decision</h3>${blockers().length?`<p class="small muted">${blockers().map(esc).join(' · ')}</p>`:notice('Evidence and credit review are complete. An authorised user can now decide whether to approve.','green')}<div class="actions">${btn('Approve guarantor','approve','primary',!canEdit()||blockers().length>0||x.status!=='submitted')}${btn('Request corrections','changes','',!canEdit()||x.status==='complete')}${btn('Reject guarantor','reject','danger',!canEdit()||x.status==='complete')}</div></div>`;}
function signing(x){return `<div class="grid2"><section class="pane"><h3>Proposed limited guarantee</h3>${rows({'Guaranteed applicant':tenant(x).name,'Joint applicant':state.tenants.find(t=>t.id!==x.tenantId).name,'Tenancy rent':money(state.property.rent)+' per month','Guaranteed rent cap':'£500 per month (50% share)','Overall liability cap':'£6,000 including covered losses and costs','Guarantee period':'1 Nov 2026 – 31 Oct 2027','Tenancy type':'Assured periodic · no fixed end date'})}<div class="actions"><a class="btn" href="${link('agreement')}">Read proposed agreement</a></div><p class="small muted spaced">Limits are sample commercial terms for review. The guarantee period does not set an end date for the tenancy.</p></section><section class="pane"><h3>Signing and acceptance</h3>${tag(x.agreement.status.replaceAll('_',' '),x.status==='complete'?'green':'amber')}${notice('Witness-free agreement proposal, not a deed. Solicitor review is required before live use. This preview cannot create a binding guarantee.')}<div class="actions">${btn('Issue sample for attestation','issue','primary',!['admin','manager'].includes(role)||x.status!=='approved'||x.agreement.status!=='not_issued')}<a class="btn" href="${link('agreement')}">Guarantor signing view</a>${btn('Simulate landlord acceptance','landlord_accept','',!['admin','manager'].includes(role)||x.agreement.status!=='guarantor_signed')}</div><p class="small muted spaced">Only a manager or administrator can issue the sample or simulate the landlord’s acceptance. A change to the submitted application invalidates the unsigned version.</p></section></div>`;}
function audit(){return `<ol class="timeline">${state.audit.map(a=>`<li><time>${date(a.at)}</time><p><strong>${esc(a.action)}</strong></p><p>${esc(a.actor)} · ${esc(a.source)}</p><p class="small muted">${esc(a.detail)}</p></li>`).join('')}</ol>`;}
function record(){const x=g(),d=(recordView==='enquiry'?state.enquiryRecords:state.tenantRecords)[x.tenantId]||x.details;return appLayout(`<div class="pagehead"><div><div class="kicker">${recordView==='enquiry'?'Tenant enquiry':'Tenant record preview'}</div><h1>${esc(tenant().name)}</h1><p class="muted">24 Example Gardens, Wolverhampton · joint applicant Casey Taylor</p></div><a class="btn" href="${link('office')}">Continue onboarding</a></div><div class="recordtabs">${btn('Enquiry record','record-enquiry','',false,`aria-pressed="${recordView==='enquiry'}"`)}${btn('Tenant record after conversion','record-tenant','',false,`aria-pressed="${recordView==='tenant'}"`)}</div><div class="grid2"><section class="card"><div class="cardhead"><h2>Guarantor</h2>${tag(statusNames[x.status],statusColour(x.status))}</div>${rows({'Name':d.name,'Email':d.email,'Telephone':d.phone,'Address':d.address,'City / town':d.city,'Postcode':d.postcode,'Date of birth':d.dob,'Relationship':d.relationship,'Employment':d.employment,'Annual income':d.income?money(d.income):'—'})}<div class="notice neutral"><div><strong>${esc(x.source)}</strong><br>${x.submittedAt?'Updated '+date(x.submittedAt)+' · revision '+x.revision:'Awaiting the guarantor’s own confirmation.'}</div></div><p class="small muted">The tenant projection demonstrates the fields copied on conversion. No live record has been converted.</p></section><section class="card"><h2>Previous details retained</h2>${x.history.length?x.history.map(h=>`<details open><summary>Revision ${h.revision} · ${esc(h.source)}</summary>${rows({'Name':h.details.name,'Email':h.details.email,'Address':h.details.address||'Not provided'})}</details>`).join(''):'<p class="muted spaced">The original nomination is retained here when the guarantor submits their form.</p>'}<h3 class="spaced">Guarantor documents</h3>${x.documents.map(d=>`<div class="doc"><strong>${esc(d.kind)}</strong> ${tag(d.current?d.review:'Superseded',d.review==='approved'?'green':'amber')}<p class="small muted">${esc(d.name)}</p></div>`).join('')||'<p class="muted spaced">No uploads yet.</p>'}</section></div>${communications()}<section class="card spaced"><h2>Activity audit</h2>${audit()}</section>`);}
function tenantForm(){const x=g();return `<main class="publicwrap"><div class="publicbrand">${brand}${tag('Tenant application · preview','blue')}</div><header class="hero"><h1>Your guarantor</h1><p>Jamie, tell us who you would like to nominate for your application at 24 Example Gardens.</p></header><section class="publicbody"><form id="tenant-form"><div class="fields">${field('Guarantor full name','name',x.details.name)}${field('Guarantor email','email',x.details.email,'email')}${field('Guarantor telephone','phone',x.details.phone,'tel')}${field('Relationship to you','relationship',x.details.relationship)}${field('Guarantor address, if known','address','','text',false,true)}</div>${check('contactAuthority','I have told this person that I am nominating them and that Fleming Lettings will contact them about becoming my guarantor.')}<p class="muted small">Your nomination does not create a guarantee. The person must complete their own application and separately agree any guarantee.</p><div class="actions"><button class="primary" type="submit">Complete sample tenant application</button><a class="btn" href="${link('record')}">See enquiry record</a></div></form>${notice('Tenant-supplied details pre-populate the enquiry immediately. If the guarantor has already submitted their own details, a later nomination is referred to the office rather than replacing them.','neutral')}</section></main>`;}
function email(){const params=new URLSearchParams(location.search),kind=params.get('kind')==='complete'?'complete':'request',message=params.get('message'),saved=(state.emails||[]).find(m=>m.id===message),actual=saved?.kind||kind,url='/demo/email?'+(saved?'message='+encodeURIComponent(saved.id):'g='+encodeURIComponent(g().id)+'&kind='+kind);return `<main class="emailwrap"><div class="emailmeta"><h1>${actual==='complete'?'Guarantor stage complete':'Guarantor request'}</h1><p class="muted spaced">To: ${esc(saved?.context.to||g().details.email)} · ${tag('Email to Guarantor','blue')}<br>Test preview — no email sent</p><div class="actions"><a class="btn ${actual==='request'?'primary':''}" href="/email?g=${g().id}&kind=request">Request email</a><a class="btn ${actual==='complete'?'primary':''}" href="/email?g=${g().id}&kind=complete">Completed email</a><a class="btn" href="${url}&download=1">Download HTML</a><a class="btn" href="${link('record')}#emails-out">Tenant communications</a></div></div><iframe class="email-frame" title="Guarantor email preview" src="${url}" sandbox="allow-same-origin allow-top-navigation-by-user-activation"></iframe><p class="small muted spaced">Your supplied HTML and images. Unconfigured social and unsubscribe destinations are inactive in this preview.</p></main>`;}
function communications(){const id=new URLSearchParams(location.search).get('applicant')||g().tenantId,entries=(state.emails||[]).filter(m=>m.linkedApplicantIds.includes(id));return `<section class="card spaced" id="emails-out"><h2>Communications</h2><div class="tabs"><button type="button" aria-pressed="true">Emails out</button></div><p class="small muted">${esc(state.tenants.find(t=>t.id===id)?.name||'Applicant')} · Guarantor messages are linked to every applicant’s enquiry and tenant record.</p>${entries.length?entries.map(m=>`<article class="doc"><div class="cardhead"><div><strong>${m.kind==='complete'?'Guarantor stage complete':'Guarantor request'}</strong><p class="small muted">To: ${esc(m.context.guarantorName)} &lt;${esc(m.context.to)}&gt;</p></div>${tag('Email to Guarantor','blue')}</div><p class="small muted">${date(m.at)} · ${esc(m.actor)} · ${esc(m.status)}</p><div class="actions"><a class="btn small" href="/email?g=${m.context.guarantorId}&message=${m.id}">View email</a></div></article>`).join(''):'<p class="muted spaced">No guarantor emails prepared yet. Select Yes in Application Review and prepare an invitation.</p>'}</section>`;}

function application(){const x=g(),token=new URLSearchParams(location.search).get('token')||x.invitation?.token;const invalid=!x.invitation||x.invitation.revoked||token!==x.invitation.token||new Date(x.invitation.expires)<new Date(),editable=['invited','changes_requested'].includes(x.status),d=x.draft||x.details;return `<main class="publicwrap"><div class="publicbrand">${brand}${tag('Your personal guarantor application','blue')}</div><header class="hero"><h1>Support someone’s next chapter.</h1><p>Confirm your details as the proposed guarantor for ${esc(tenant().name)}. We’ll guide you through the information and documents we need.</p></header><section class="publicbody">${invalid?notice('This link is not available. It may have expired or been withdrawn. Please ask the office for a new invitation.','red'):!editable?`${notice('Your application has been received. The office will review your details and documents. Your application declaration is not a signed financial guarantee.','green')}<h2>${esc(statusNames[x.status])}</h2><p class="spaced">Submitted ${date(x.submittedAt)} · revision ${x.revision}</p><div class="actions"><a class="btn" href="${link('agreement')}">View guarantee status</a><a class="btn" href="${link('office')}">Return to office preview</a></div>`:`<form id="guarantor-form"><div class="section-title"><h2><span class="num">01</span> The applicant you are supporting</h2></div><div class="grid3"><div class="labelvalue">Applicant<strong>${esc(tenant().name)}</strong></div><div class="labelvalue">Property<strong>24 Example Gardens</strong></div><div class="labelvalue">City / town<strong>Wolverhampton</strong></div></div>${check('confirmApplicant',`I confirm I am applying to act as guarantor for <strong>${esc(tenant().name)}</strong> at this property.`)}${btn('I cannot act as guarantor / wrong applicant','decline','small danger')} ${x.reason?notice('<strong>Please correct the following</strong><br>'+esc(x.reason),'red'):''}<div class="section-title"><h2><span class="num">02</span> About you</h2></div><div class="fields">${field('Full legal name','name',d.name)}${field('Date of birth','dob',d.dob,'date')}${field('Email address','email',d.email,'email')}${field('Telephone','phone',d.phone,'tel')}${field('Relationship to the applicant','relationship',d.relationship)}${selectField('Employment status','employment',[['','Choose…'],['Employed','Employed'],['Self-employed','Self-employed'],['Retired','Retired'],['Other','Other / not currently working']],d.employment)}${field('Employer / income source','employer',d.employer,'text',false)}${field('Gross annual income (£)','income',d.income,'number')}</div><div class="section-title"><h2><span class="num">03</span> Address history</h2></div><div class="fields">${field('Current address','address',d.address,'text',true,true)}${field('City / town','city',d.city)}${field('Postcode','postcode',d.postcode)}${field('Living here since','addressSince',d.addressSince,'date')}<label class="field wide">Previous addresses if at your current address less than three years<textarea name="previousAddress" placeholder="Include addresses, postcodes and dates covering the last three years">${esc(d.previousAddress)}</textarea></label></div><div class="section-title"><h2><span class="num">04</span> Supporting documents</h2></div><p class="muted">Upload a PDF, JPEG or PNG up to 10 MB per category. For this demonstration, use sample documents only.</p>${['Primary ID','Secondary ID','Bank statements'].map((kind,i)=>{const doc=x.documents.find(d=>d.current&&d.kind===kind);return `<div class="upload"><strong>${kind}</strong><p class="small muted">${['Photo identity document, such as a passport or driving licence.','Separate address evidence, such as a recent utility bill or council tax statement.','Recent statements covering three months. Keep name, dates, balances and relevant income visible; ask the office about redacting unrelated sensitive information.'][i]}</p>${doc?`<p class="small spaced">✓ ${esc(doc.name)} · ${esc(doc.review)}</p>`:''}<label class="field"><span class="sr-only">Upload ${kind}</span><input type="file" data-upload="${kind}" accept="application/pdf,image/png,image/jpeg"></label></div>`}).join('')}<div class="actions">${btn('Fill fictional details','sample-details','small')}${btn('Attach three sample documents','sample-docs','small')}<a class="btn small" href="/sample.pdf" download="fictional-sample.pdf">Download sample PDF</a></div><div class="section-title"><h2><span class="num">05</span> Your declarations</h2></div><div class="checks">${check('truth','The information I have supplied is accurate and complete to the best of my knowledge. I will tell the office about relevant changes.')}${check('understanding','I understand that a separate guarantee could require me to pay covered rent or loss if the applicant defaults. I will read its limits and the proposed tenancy and can seek independent legal advice before signing. This application itself is not the guarantee.')}${check('privacy','I have read the privacy information below and understand how my information will be used for this application.')}${check('creditAuthority','I authorise the proposed referencing and credit check described to me. In this preview, no provider is contacted and no credit search is made.')}</div><details><summary>Privacy information for this preview</summary><p>This prototype stores fictional answers and uploaded files only on this computer. They are not sent to Fleming’s live CRM, Canopy, email or SMS services. Office and applicant screens share the demonstration state.</p><p>Before production, Fleming must publish its controller details, lawful basis, credit-reference provider and search impact, recipients, retention periods, rights and contact route. Bank statements and ID must be restricted to authorised reviewers. Do not upload real personal documents here.</p></details><div class="actions"><button type="submit" class="primary">Submit guarantor application</button>${btn('Save progress','save-draft')}${btn('Ask the office for help','help','small')}</div><p class="small muted spaced">Required fields are marked *. Submission updates your details in the linked enquiry and tenant-record preview. Office approval is a separate step.</p></form>`}</section><footer class="footer">Fleming Lettings · Guarantor application preview · No legal commitment is created</footer></main>`;}
function agreement(){const x=g(),a=x.agreement;return `<main class="contract"><div class="kicker">Proposed terms for review · England · 29 September 2026</div><h1>Limited guarantee agreement</h1>${notice('<strong>NON-BINDING TEST DRAFT — not for signature or use in a real tenancy.</strong><br>This proposal removes the deed and witness blocks. A solicitor must approve the replacement agreement, consideration and signing sequence before live use.','red')}<div class="grid2"><div>${rows({'Landlord':state.property.landlord,'Guarantor':x.details.name,'Guaranteed applicant':tenant().name,'Property':'24 Example Gardens, Wolverhampton, WV10 9TG'})}</div><div>${rows({'Version':'G-2026-preview-1','Rent contribution':'£500 monthly · 50%','Aggregate cap':'£6,000','Status':a.status.replaceAll('_',' ')})}</div></div><p>The amounts and duration below are deliberately explicit for this demonstration. They are proposed business terms requiring approval, not statements of what the law requires. Each guarantor must be associated with the named applicant and a versioned tenancy document.</p>${clauses.map(([title,text],i)=>`<h2>${i+1}. ${esc(title)}</h2><p>${esc(text).replaceAll('[GUARANTEED_APPLICANT]',esc(tenant().name)).replaceAll('[OTHER_APPLICANT]',esc(state.tenants.find(t=>t.id!==x.tenantId).name))}</p>`).join('')}<h2>Schedule and signing record</h2><p>Landlord notice address for this fictional example: 18 Sample Avenue, Wolverhampton, WV10 9TG. Agent: Fleming Lettings, Creative Industries Centre, Glaisher Drive, Wolverhampton, WV10 9TG, acting only within the landlord’s confirmed authority.</p><p>Tenancy reference: proposed assured periodic tenancy schedule T-2026-preview-1. A final complete tenancy agreement has not been supplied in this prototype; uploading and locking its final version is a mandatory production gate.</p>${a.status==='issued'?`<form id="sign-form" class="pane no-print"><h3>Try the guarantor attestation</h3>${field('Type your full name','typedName','','text')}${check('ack','I have read this non-binding demonstration and understand the proposed limits, the separate tenancy, and my opportunity to take advice. I am trying the preview only; no legal agreement is created.')}<button type="submit" class="primary">Record sample attestation</button></form>`:a.status==='guarantor_signed'||a.status==='complete'?notice('Sample attestation recorded for '+esc(a.signer)+' on '+date(a.signedAt)+'. '+(a.status==='complete'?'Landlord acceptance has also been simulated.':'Awaiting simulated landlord acceptance.'),'green'):notice('The office must review the guarantor and issue the sample before this attestation step is available.','neutral')}<div class="actions no-print">${btn('Print / save draft','print')}<a class="btn" href="${link('office')}">Back to office review</a><a class="btn" href="/plan">Legal review and test plan</a></div><h2>Sources and review scope</h2><p class="small">Research checked 29 September 2026. This draft cannot cover every possible dispute or guarantee enforceability. Obtain a qualified English housing solicitor’s review before using it.</p><ul class="source-list small">${sources.slice(0,6).map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noreferrer">${t}</a></li>`).join('')}</ul></main>`;}
function plan(){return `<main class="contract"><div class="kicker">Design and acceptance plan</div><h1>Guarantor onboarding preview</h1><p>Review the complete local journey, then agree the legal and operational choices before any production implementation. This prototype uses a separate local store, fictional people, sample files, simulated roles and simulated credit reports.</p><h2>Try the journey</h2><ol><li>Open the office stage and preview the email.</li><li>Open the guarantor form. Use “Fill fictional details” and “Attach three sample documents”, confirm the applicant and declarations, and submit.</li><li>Open the record to see the guarantor’s answers replace the nomination. The prior data remains in history.</li><li>Return to “Review & credit”, approve or reject documents, and try requesting corrections. Run the demo check, receive its report and record an office review.</li><li>Approve the guarantor, then as a manager issue the sample agreement. Open the signing view, record a sample attestation, and simulate landlord acceptance.</li><li>Try the viewer role, a withdrawn invitation and a rejected guarantor. Reset to repeat.</li></ol><h2>Changes from the old deed</h2><p>The supplied “Limited Deed of Guarantee Form - V3.26” describes a 12-month tenancy, continued periodic liability, broad non-rent indemnity, changes without consent and extensive legal-cost recovery. The proposed agreement uses a periodic tenancy, named applicant scope, clear financial and time limits, no blanket indemnity and separate evidence-based demands. It replaces the old tenant-death wording.</p><p>Removing witnessing is a change in legal form, not just layout. Individuals’ deeds still require the statutory execution formalities. The preview therefore proposes a signed written guarantee supported by consideration before the tenancy is granted. Existing tenancies, late signing, companies, vulnerable signers, undue influence and capacity concerns need specific advice.</p><h2>Legal approval checklist</h2><ul><li>Confirm English assured periodic tenancy scope and commencement rules for the actual case; do not use this for Wales, Scotland, company lets or excluded tenancies.</li><li>Confirm consideration, timing, landlord authority, written signature evidence and the full tenancy version supplied before commitment.</li><li>Approve the proposed £500 monthly / £6,000 aggregate limits and one-year guarantee period. Define other covered losses, payment attribution and early release without unfair terms.</li><li>Check statutory tenant-death protection, joint-family relationships, daily rent apportionment and accrued arrears. Preserve all protections in sections 16N and 16P.</li><li>Review rent variations, substitutions, insolvency, guarantor death, cancellation requests, consumer fairness, Tenant Fees Act restrictions, service of notices, court costs, limitation and applicable pre-action procedures.</li><li>Confirm privacy notices, legal basis for referencing, retention and access; consider equality and reasonable adjustments. No automatic housing decision from a score or protected characteristic.</li></ul><h2>Canopy integration preparation</h2><p>The current Canopy documentation supports a <code>GUARANTOR_SCREENING</code> referencing request. The production adapter should be server-side and configurable for Canopy sandbox / production credentials and branches. The prototype uses a demo provider, so no credential or provider call exists.</p><p>Persist the guarantor ID, linked applicant IDs, application revision, internal request ID and provider reference. Match authenticated callbacks to that request, deduplicate events, tolerate delayed or out-of-order updates, and retain a versioned report. A received report updates status; only authorised staff may record the final decision. Confirm callback authentication and the contracted request product directly with Canopy before connection.</p><details><summary>Verified request mapping</summary><pre style="white-space:pre-wrap">POST /referencing-requests/client/:clientId/request
requestType: GUARANTOR_SCREENING
itemType: FULL (confirm contracted product)
email, firstName, lastName, phone
clientReferenceId: guarantor ID + application revision
branchId: configured branch mapping
callbackUrl: protected backend report receiver</pre><p class="small">Register supported request / passport status webhooks. Do not invent a signing algorithm, assume report completion equals approval, or re-run a paid check automatically after a timeout.</p></details><h2>Data and access model for production</h2><p>Use a first-class guarantor record with explicit applicant / tenancy links, versioned submissions, documents, referencing requests, decisions, invitations, agreement versions and events. Retain the legacy <code>app_guarantor_*</code> enquiry fields and <code>guarantor_*</code> tenant fields as compatibility projections. Copy only validated permitted fields; never overwrite tenant identity or automatically set KYC and deed flags.</p><p>On submission, update the linked enquiry and any already-linked tenant atomically, store provenance and prior values, notify the assigned office and preserve the original nomination. Additional guarantors and joint applicants remain separate; one person supporting both needs explicit scope and a reviewed agreement.</p><p>Production must use the CRM’s real permissions and portfolio scope on every request. Viewers cannot change or approve; public tokens only access their invitation. Use hashed expiring/revocable tokens, email identity confirmation, CSRF/rate limits, private encrypted storage, file signature/size checks, malware scanning and an approved retention policy. Tenants must not see guarantors’ bank statements or reports. The role switch and shared state in this local demo are not production security.</p><p>Record actual staff and guarantor names, timestamps, actions, versions and before/after values. Future FlemoAI-assisted office actions must obey the same checks and add “Done by FlemoAI” alongside the acting user; the assistant cannot override permissions or approve referencing automatically.</p><h2>Test matrix</h2><table class="table"><thead><tr><th>Area</th><th>Test</th><th>Expected result</th></tr></thead><tbody>${testCases.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')}</tbody></table><h2>Before anything goes live</h2><p>Your approval of the preview, solicitor approval of the final agreement, privacy review, production integration and security tests, and a Canopy sandbox test are required. No guarantor prototype code or data is included in the live CRM release.</p><h2>Source references</h2><ul class="source-list">${sources.map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noreferrer">${t}</a></li>`).join('')}</ul></main>`;}
function render(){const fn={office,record,tenant:tenantForm,email,apply:application,agreement,plan}[page]||office;document.body.classList.toggle('office-page',page==='office');$('#app').innerHTML=shell(fn(),['tenant','email','apply','agreement','plan'].includes(page));document.title='Fleming Lettings · '+({office:'Guarantor onboarding',apply:'Guarantor application',record:'Guarantor record',agreement:'Proposed guarantee',tenant:'Tenant nomination',email:'Guarantor email',plan:'Test plan'}[page]||'Preview');}
function modal(title,body,kind){$('#modal').innerHTML=`<header><h2>${title}</h2>${btn('×','close','icon',false,'aria-label="Close dialog"')}</header><form data-modal="${kind}">${body}<div class="actions"><button type="submit" class="primary">Confirm</button>${btn('Cancel','close')}</div></form>`;$('#modal').showModal();}
function draftDetails(){return Object.fromEntries(new FormData($('#guarantor-form')));}
async function upload(kind,file){const f=new FormData();f.append('file',file);f.append('kind',kind);f.append('g',g().id);f.append('token',new URLSearchParams(location.search).get('token')||g().invitation?.token||'');const r=await fetch('/demo/upload',{method:'POST',body:f});const v=await r.json();if(!r.ok)throw Error(v.error);return v;}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,x=g();
 if(action==='require-yes'||action==='require-no'){await act({type:'requirement',tenantId:reviewApplicant,required:action==='require-yes'});return;}
 if(action==='close'){return $('#modal').close();}if(action==='tab'){officeTab=button.dataset.tab;return render();}if(action==='record-enquiry'||action==='record-tenant'){recordView=action==='record-enquiry'?'enquiry':'tenant';return render();}
 if(action==='sample-details'){const sample={name:'Robin Taylor',email:'robin.taylor@example.test',phone:'07700900321',dob:'1975-04-12',relationship:'Parent',employment:'Employed',employer:'Willow Design Studio',income:'48000',address:'8 Willow Close',city:'Wolverhampton',postcode:'WV10 9TG',addressSince:'2018-02-01',previousAddress:''};for(const [k,v] of Object.entries(sample))$('#guarantor-form').elements[k].value=v;return toast('Fictional details filled. Read and tick the declarations yourself.');}
 if(action==='sample-docs'){try{const current=draftDetails();await act({type:'save_draft',g:x.id,token:x.invitation.token,details:current});const blob=await fetch('/sample.pdf').then(r=>r.blob());for(const kind of ['Primary ID','Secondary ID','Bank statements'])await upload(kind,new File([blob],'Sample '+kind+'.pdf',{type:'application/pdf'}));await refresh(true);toast('Three clearly marked sample documents attached.');}catch(err){toast(err.message);}return;}
 if(action==='save-draft'){await act({type:'save_draft',g:x.id,token:x.invitation.token,details:draftDetails()});return toast('Progress saved in the local preview.');}
 if(action==='print')return window.print();

 if(action==='notifications'){await act({type:'read_notifications'});$('#modal').innerHTML=`<header><h2>Notifications</h2>${btn('×','close','icon')}</header><div class="content">${state.notifications.length?state.notifications.map(n=>`<div class="doc"><a href="/office?g=${n.g}">${esc(n.text)}</a><p class="small muted">${date(n.at)}</p></div>`).join(''):'No notifications yet.'}</div>`;$('#modal').showModal();return;}
 if(action==='help')return toast('Preview help: call 01902 212 415 or contact your lettings manager. No message has been sent.');
 if(action==='add'){return modal('Add a guarantor',`<div class="fields">${selectField('Supporting applicant','tenantId',state.tenants.map(t=>[t.id,t.name]),reviewApplicant)}${field('Name','name')}${field('Email','email','','email')}${field('Telephone','phone','','tel',false)}${field('Relationship','relationship','','text',false)}</div>`,'add');}
 if(['changes','reject','decline','credit-review','doc-reject'].includes(action)){button.dataset.doc&&($('#modal').dataset.doc=button.dataset.doc);return modal({changes:'Request corrections',reject:'Reject guarantor',decline:'Unable to act as guarantor','credit-review':'Record credit report review','doc-reject':'Reject document'}[action],`<label class="field">${action==='credit-review'?'Record your review and whether the evidence is satisfactory for this demonstration':'Reason to record and show to the guarantor'}<textarea name="reason" required></textarea></label>`,action);}
 if(action==='issue')return modal('Issue non-binding sample',`${check('legalDemo','I am simulating legal approval for this test only. The proposed agreement is not approved for live use.')}${check('beforeTenancy','The scenario is a new tenancy before grant. The final tenancy version, consideration and signature sequence will be checked before production.')}`,'issue');
 if(action==='reset')return modal('Reset the demonstration','<p>This resets only the fictional local prototype. Nothing in the live CRM is affected.</p>','reset');
 if(action==='doc-approve'){await act({type:'document_review',g:x.id,documentId:button.dataset.doc,decision:'approved'});return;}
 const success=await act({type:action,g:x.id,revision:x.revision});if(success&&action==='invite')toast('Test invitation prepared. Open the email preview; no email was sent.');
});
document.addEventListener('change',async e=>{if(e.target.id==='review-applicant'){reviewApplicant=e.target.value;return render();}if(e.target.id==='demo-role'){role=e.target.value;sessionStorage.setItem('guarantor-demo-role',role);return render();}if(e.target.id==='guarantor-picker'){selected=e.target.value;return render();}if(e.target.dataset.upload&&e.target.files[0]){const draft=draftDetails();try{await upload(e.target.dataset.upload,e.target.files[0]);await act({type:'save_draft',g:g().id,token:g().invitation.token,details:draft});toast('Document uploaded for office review.');}catch(err){toast(err.message);}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),x=g();if(form.id==='tenant-form'){if(await act({type:'nominate',tenantId:'83',details:d}))toast('Tenant nomination saved. Check the linked enquiry record.');return;}if(form.id==='guarantor-form'){await act({type:'submit',g:x.id,revision:x.revision,token:new URLSearchParams(location.search).get('token')||x.invitation.token,tenantId:x.tenantId,details:d,confirmApplicant:!!d.confirmApplicant,truth:!!d.truth,privacy:!!d.privacy,creditAuthority:!!d.creditAuthority,understanding:!!d.understanding});return;}if(form.id==='sign-form'){await act({type:'sign',g:x.id,token:new URLSearchParams(location.search).get('token')||x.invitation?.token,...d,ack:!!d.ack});return;}const kind=form.dataset.modal;let body={type:kind,g:x.id,revision:x.revision,...d};if(kind==='add')body={type:'add',tenantId:d.tenantId,details:d};if(kind==='doc-reject')body={type:'document_review',g:x.id,documentId:$('#modal').dataset.doc,decision:'rejected',reason:d.reason};if(kind==='credit-review')body.type='credit_review';if(kind==='decline')body.token=x.invitation.token;if(kind==='issue'){body.legalDemo=!!d.legalDemo;body.beforeTenancy=!!d.beforeTenancy;}if(await act(body))$('#modal').close();});
window.addEventListener('focus',()=>{if(!document.activeElement?.matches('input,textarea,select'))refresh().catch(()=>{});});
await refresh(true);
